parameters.jsCode:
const briefSummary = $items('SummarizeBriefGemini')[0].json;
const toolSchema = $items('ReadOpenAPISchema')[0].json;

const agentWorkflow = {
  agent_name: 'FreyaBankVoiceAgent',
  version: '1.0.0',
  system_prompt: 'Bankacilik sesli asistanisin. Is gunleri ve tatil vadelerine gore hesaplama yaparsin.',
  tools: toolSchema.tools || [],
  nodes: [
    { id: 'greeting', type: 'voice_prompt', text: 'Hos geldiniz, size nasil yardimci olabilirim?' },
    { id: 'check_due_date', type: 'action_step', handler: 'date_calculator' },
    { id: 'handoff_agent', type: 'transfer', condition: 'transfer_requested' }
  ]
};

const isValid = Boolean(agentWorkflow.agent_name && agentWorkflow.nodes.length > 0);

return [{ json: { workflowSpec: agentWorkflow, isValid } }];

const spec = $json.workflowSpec || {};
spec.agent_name = spec.agent_name || 'FreyaBankVoiceAgent_Recovered';
spec.nodes = spec.nodes || [{ id: 'fallback', type: 'voice_prompt', text: 'Size nasil yardimci olabilirim?' }];
spec.fixed = true;
return [{ json: { workflowSpec: spec, isValid: true } }];
